cat > /tmp/diff.pl <<'PERL'
use strict; use warnings;
my $B = "/workspace/dataset/test15_executable";
sub run {
  my ($w) = @_;
  my ($o,$e);
  open(my $oldout, ">&", STDOUT); open(my $olderr, ">&", STDERR);
  my $pid = open(my $fh, "-|");
  die unless defined $pid;
  if ($pid == 0) { open(STDERR, ">", "/tmp/e.$$.txt"); exec($B, $w); exit 127; }
  local $/; $o = <$fh>; $o = "" unless defined $o; close($fh); my $ec = $?;
  my $ef = "/tmp/e.".($pid).".txt";
  # child's $$ equals pid
  if (open(my $g, "<", $ef)) { local $/; $e = <$g>; close $g; unlink $ef; } else { $e = "" }
  $e = "" unless defined $e;
  return ($o, $e, $ec);
}
sub predict {
  my ($w) = @_;
  my $s = "Module::".$w;
  my $pos = rindex($s, ":");
  my $start = $pos + 2;
  if ($start > length($s)) { return (undef, sprintf("terminate called after throwing an instance of 'std::out_of_range'\n  what():  basic_string::substr: __pos (which is %d) > this->size() (which is %d)\n", $start, length($s))); }
  return (substr($s, $start), undef);
}
my @alpha = ('a','b',':','::',':::','x','Y','_',' ','-',"\xc3\xa9",'q','.','/','|',';',"\t",'0','Z',"\xba","\xff","\x01","\xe6\x97\xa5",'#','A');
my $mm = 0; my $n = 0;
srand($ARGV[1] // 12345);
my $N = $ARGV[0] // 300;
for my $it (1..$N) {
  my $len = int(rand(9));
  my $w = "";
  $w .= $alpha[int(rand(scalar @alpha))] for (1..$len);
  next if $w =~ /\n/;
  $n++;
  my ($po,$pe) = predict($w);
  my ($o,$e,$ec) = run($w);
  my $ok;
  if (defined $pe) { $ok = ($ec != 0 && $e eq $pe); }
  else { $ok = ($ec == 0 && substr($o, length($o)-length($po)-1) eq $po."\n"); }
  unless ($ok) {
    $mm++;
    printf("MISMATCH W=[%s] hex=%s\n  pred=%s\n  gotout_tail=%s\n  ec=%d err=[%s]\n", $w, unpack("H*",$w), (defined $pe ? "CRASH:$pe" : unpack("H*",$po)), unpack("H*", substr($o, (length($o)>20? length($o)-20:0))), $ec>>8, $e);
    last if $mm > 12;
  }
}
printf("tested=%d mismatches=%d\n", $n, $mm);
PERL
